parameters.jsCode:
// Clean the inbound email into query text (mirror of WF1 cleaning).
// Runs once per item on the loop's done branch; the record arrives complete
// (raw message + threadHistory) from "Code - Attach Thread".
const m = $json;
const decode = s => String(s || '').replace(/&nbsp;/gi,' ').replace(/&amp;/gi,'&').replace(/&lt;/gi,'<').replace(/&gt;/gi,'>').replace(/&quot;/gi,'"').replace(/&#39;/gi,"'");
const cutHtml = s => { s = String(s || ''); const M = [/appendonsend/i, /border-top:\s*solid/i, /gmail_quote/i, /<blockquote/i]; let c = s.length; for (const rx of M) { const mm = s.match(rx); if (mm && mm.index >= 0 && mm.index < c) c = mm.index; } const lt = s.lastIndexOf('<', c); if (lt >= 0) c = lt; return s.slice(0, c); };
const cutText = s => { s = String(s || ''); const M = [/-{2,}\s*Original Message\s*-{2,}/i, /\bOn .{0,160}\bwrote:/i, /\bFrom:\s.{0,120}\bSent:\s/i, /\bGet Outlook for /i]; let c = s.length; for (const rx of M) { const mm = s.match(rx); if (mm && mm.index >= 0 && mm.index < c) c = mm.index; } return s.slice(0, c); };
const strip = h => cutText(decode(cutHtml(String(h || '')).replace(/<[^>]+>/g,' ').replace(/<\/?[a-z!][^>]*$/i,' '))).replace(/\s+/g,' ').trim();
const subject = m.subject || '';
const body = strip((m.body && m.body.content) || m.bodyPreview || '');
const inbound_from = (m.from && m.from.emailAddress && m.from.emailAddress.address) || '';

// --- Forwarded-mail detection -------------------------------------------
// cutHtml() above slices at <div id="appendonsend"> / blockquote, which is
// exactly the seam between a forwarder's covering note and the forwarded
// block. Capture the UNCUT html here so the forwarded branch can recover the
// original enquiry; queryText keeps its existing (cut) value as the fallback.
const rawHtml = String((m.body && m.body.content) || '').slice(0, 65536);
const baseSubject = String(subject).replace(/^(\s*(re|res|aw|sv|vs|antwort)\s*(\[\d+\])?\s*:\s*)+/i, '').trim();
const isForwarded = /^(fw|fwd|fwd?d|tr|wg|rv|enc)\s*(\[\d+\])?\s*:/i.test(baseSubject);
const stripChrome = s => String(s || '')
  .replace(/<table\b(?:(?!<\/?table\b)[\s\S])*?External Email(?:(?!<\/?table\b)[\s\S])*?<\/table>/gi, ' ');

// Derive sender_role from the inbound sender domain.
// MUST match WF-1's ingestion logic EXACTLY (symmetric preprocessing) so the
const roleFor = (address) => {
  const addr = String(address || '').trim().toLowerCase();
  const at = addr.lastIndexOf('@');
  const domain = at >= 0 ? addr.slice(at + 1) : '';

  if (!domain) return 'unknown';

  // Student domains
  if (
    domain === 'u.nus.edu' ||
    domain.endsWith('.u.nus.edu') ||
    domain === 'u.yale-nus.edu.sg' ||
    domain.endsWith('.u.yale-nus.edu.sg') ||
    domain === 'u.duke.nus.edu' ||
    domain.endsWith('.u.duke.nus.edu')
  ) {
    return 'student';
  }

  // Visitor domains
  if (
    domain === 'visitor.nus.edu.sg' ||
    domain.endsWith('.visitor.nus.edu.sg') ||
    domain === 'partner.nus.edu.sg' ||
    domain.endsWith('.partner.nus.edu.sg')
  ) {
    return 'visitor';
  }

  // Staff domains
  if (
    domain === 'nus.edu.sg' ||
    domain.endsWith('.nus.edu.sg')
  ) {
    return 'staff';
  }

  return 'external';
};

return { json: {
  inbound_subject: subject,
  inbound_from,
  inbound_from_name: (m.from && m.from.emailAddress && m.from.emailAddress.name) || '',
  inbound_message_id: m.id || '',
  conversation_id: m.conversationId || '',
  // internet_message_headers: headers,
  threadHistory: $json.threadHistory || '',
  sender_role: roleFor(inbound_from),
  queryText: body.slice(0, 8000),
  inbound_to: m.toRecipients || [],
  inbound_cc: m.ccRecipients || [],
  question_received_at: $json.sentDateTime,
  is_forwarded: isForwarded,
  fwd_source: 'none',              // set to covering|quoted on the forwarded branch
  fwd_original_sender: '',         // quoted From: address, when source === 'quoted'
  _fwd_html: isForwarded ? rawHtml : '',
  _fwd_clean_html: isForwarded ? stripChrome(rawHtml) : ''
}};

