parameters.jsCode:
// Replace queryText with the LLM-cleaned question body (subject re-prefixed).
// Reads $json rather than $('Build Query').item: the forwarded branch puts an
// Agent upstream of this node, and pairedItem lineage does not survive an Agent
// -- the record now arrives here already merged by "Merge - Query + Cleaned".
const { output, _fwd_html, _fwd_clean_html, _fwd_md, ...orig } = $json;
const cleaned = String((output && output.text) || '').trim();
const bodyForQuery = cleaned || orig.queryText || '';
const queryText = `Subject: ${orig.inbound_subject || ''}\n\n${bodyForQuery}`.slice(0, 8000);
return { json: { ...orig, queryText } };

options.systemMessage:
=You are a front-desk assistant drafting email replies for a university counselling service's shared mailbox. The user message is ONLY the latest inbound email to answer; THREAD HISTORY (below) is earlier context in the same thread. Use it for continuity: honour what was already promised, asked, or agreed; don't contradict it; don't repeat information already given unless it helps. ALWAYS first use the available tool to search past sent emails for ones similar to the latest inbound email - each result is a past inbound question and (in its metadata) the reply that was actually sent. Study those sent replies and write a new reply in the SAME tone, structure, and formality. Ground your reply strictly in the latest inbound email, the thread history, and the retrieved precedents - do NOT invent facts, names, dates, policies, links, phone numbers, or commitments. PRESERVE HYPERLINKS: when a retrieved precedent's reply_text contains a URL or hyperlink (e.g. a booking link, online form, or resource page) that is relevant to the latest inbound email, reproduce that link EXACTLY as it appears in the precedent - do not omit, truncate, shorten, paraphrase, or re-format it, and keep it attached to the same descriptive wording it carried in the precedent. Only include links that appear verbatim in the retrieved precedents or the thread history; never fabricate, complete, or guess a URL. If key information is missing, write a brief, polite holding reply. Output ONLY the email body: begin with the greeting and end at the final sentence of substantive content, then STOP. No subject line, no preamble, no explanations.

THREAD HISTORY (earlier messages in this conversation, oldest first; empty if this is the first message in the thread):
{{ $json.threadHistory }}

parameters.jsCode:
// Build a chronological plain-text history of THIS conversation's prior messages.
// Reuses the same cleaning as Build Query. Excludes the email we are replying to
// (so it is not duplicated) and defensively keeps only same-conversation messages.
const orig = $('Skip Unwanted emails').first().json;
const src = $('Loop Over Inbound').first().json;
const convId = src.conversationId || '';
const currentId = src.id || '';
const decode = s => String(s || '').replace(/&nbsp;/gi,' ').replace(/&amp;/gi,'&').replace(/&lt;/gi,'<').replace(/&gt;/gi,'>').replace(/&quot;/gi,'"').replace(/&#39;/gi,"'");
const cutHtml = s => { s = String(s || ''); const M = [/appendonsend/i, /border-top:\s*solid/i, /gmail_quote/i, /<blockquote/i]; let c = s.length; for (const rx of M) { const m = s.match(rx); if (m && m.index >= 0 && m.index < c) c = m.index; } const lt = s.lastIndexOf('<', c); if (lt >= 0) c = lt; return s.slice(0, c); };
const cutText = s => { s = String(s || ''); const M = [/-{2,}\s*Original Message\s*-{2,}/i, /\bOn .{0,160}\bwrote:/i, /\bFrom:\s.{0,120}\bSent:\s/i, /\bGet Outlook for /i]; let c = s.length; for (const rx of M) { const m = s.match(rx); if (m && m.index >= 0 && m.index < c) c = m.index; } return s.slice(0, c); };
const strip = h => cutText(decode(cutHtml(String(h || '')).replace(/<[^>]+>/g,' ').replace(/<\/?[a-z!][^>]*$/i,' '))).replace(/\s+/g,' ').trim();
const ts = m => new Date(m.sentDateTime || m.receivedDateTime || m.createdDateTime || 0).getTime();
const msgs = $input.all().map(i => i.json).filter(m => m && (m.conversationId || '') === convId && (m.id || '') !== currentId).sort((a, b) => ts(a) - ts(b)).slice(-5); // keep only the 5 most recent past messages (current msg already excluded above)
const lines = msgs.map(m => {
  const ea = m.from && m.from.emailAddress;
  const who = (ea && (ea.name || ea.address)) || 'Unknown';
  const when = m.sentDateTime || m.receivedDateTime || '';
  const body = strip((m.body && m.body.content) || m.bodyPreview || '');
  if (!body) return '';
  return `--- From: ${who} | ${when} ---\n${body.slice(0, 2000)}`;
}).filter(Boolean);
const threadHistory = lines.length ? lines.join('\n\n').slice(0, 12000) : '';
return [{ json: { ...orig, threadHistory } }];

