parameters.jsCode:
// Reads "Merge - Consult Branches",
// skip the intent classifier entirely (If Consult Required? true -> Set -
// Intent Consult), so Apply Intent has no item for them. Merge - Consult
// Branches is the first node both paths pass through, so it is the only safe
// target -- and being append-mode, it propagates pairedItem.
const orig = $('Merge - Consult Branches').item.json;
const parsed = $json.output || {};
const cleaned = (parsed.text == null ? '' : String(parsed.text)).trim();
const threadHistory = cleaned || orig.threadHistory || '';
return { json: { ...orig, threadHistory } };

// Flag automated / system-generated mail that needs no human reply.
// Header signals come from the Graph fetch ($json.internetMessageHeaders);
// subject + body come from the original inbound item. The Unwanted? IF node
// routes flagged items back to the loop so the batch keeps advancing.
const src = $('Loop Over Inbound').item.json;
const hdrs = $json.internetMessageHeaders || src.internetMessageHeaders || [];
const subject = String(src.subject || '').trim();
const prev = String(src.bodyPreview || '').slice(0, 200).toLowerCase();
const get = n => { const h = hdrs.find(x => String(x.name || '').toLowerCase() === n); return h ? String(h.value || '').toLowerCase() : ''; };
let unwanted = false;
// Subject patterns: auto-reply / OOO / bounce / receipt
if (/^(automatic reply|auto[- ]?reply|out of office|undeliverable|delivery (status notification|has failed|failure)|mail delivery|returned mail|read:|not read:|accepted:|declined:|tentative:|canceled:|cancelled:)/i.test(subject)) unwanted = true;
// Standard automated headers
const autoSub = get('auto-submitted'); if (autoSub && autoSub !== 'no') unwanted = true;
if (get('x-auto-response-suppress')) unwanted = true;
if (/(auto_reply|list|bulk|junk)/.test(get('precedence'))) unwanted = true;
if (get('x-autoreply') === 'yes' || get('x-autorespond')) unwanted = true;
// Lists / bulk senders
if (get('list-unsubscribe') || get('list-id') || src.unsubscribeEnabled === true) unwanted = true;
const rp = get('return-path'); if (rp === '<>' || /mailer-daemon|postmaster/.test(rp)) unwanted = true;
if (get('feedback-id') || get('x-feedback-id')) unwanted = true;
if (/sendgrid|amazonses|mailgun|mailchimp|mandrill|sparkpost|marketo|constantcontact/.test(get('x-mailer'))) unwanted = true;
// System / no-reply sender (From or Reply-To local-part) + loop-prevention header.
const pickAddr = s => { s = String(s || ''); const mm = s.match(/<([^>]+)>/); return (mm ? mm[1] : s).toLowerCase().trim(); };
const addrFrom = pickAddr((src.from && src.from.emailAddress && src.from.emailAddress.address) || get('from'));
const addrReply = pickAddr(get('reply-to') || (src.replyTo && src.replyTo[0] && src.replyTo[0].emailAddress && src.replyTo[0].emailAddress.address));
// Explicit blocked senders (lowercase; addrFrom/addrReply are already lowercased)
const BLOCKED = ['nospammail@nus.edu.sg', 'ucs-qualtrics@se.nus.edu.sg'];
if (BLOCKED.includes(addrFrom) || BLOCKED.includes(addrReply)) unwanted = true;
const isNoReply = a => /(^|[._+-])(no[._-]?reply|do[._-]?not[._-]?reply|donotreply|notifications?|mailer|maildaemon|mailer-daemon|bounces?|postmaster|automated|alerts?)([._+-]|$)/i.test(String(a).split('@')[0] || '');
if (isNoReply(addrFrom) || isNoReply(addrReply)) unwanted = true;
if (get('x-loop')) unwanted = true;
// Body fallback: OOO phrasing
if (/i am (currently )?(away|out of (the )?office)|on (annual |medical )?leave|automatic reply|this is an automated/.test(prev)) unwanted = true;
return { json: { ...$json, __unwanted: unwanted } };

