parameters.jsCode:
// Rebuild prior-message turns from a forwarded email's own quoted blocks, and
// drop the branch's scratch keys before the item continues downstream.
//
// Why: roughly half of forwarded mail arrives on a NEW conversationId, so the
// Inbox/Sent lookup in Stage 4 returns nothing and "Has Thread History?" goes
// false. The quoted chain inside the forward is the only history that exists
// for those. Output format matches Build Thread History exactly, so the same
// "Clean Thread History (LLM)" node handles both sources unchanged.
//
// sender_role is deliberately NOT re-derived here: WF-1b derives it from the
// forwarder's resolved address, and the two workflows must stay symmetric or
// retrieval filters stop matching what was indexed.
//
// MODE: "Run Once for All Items" -- every input item is processed and emitted,
// one output per input, with pairedItem set so downstream reach-backs resolve.
const CAP_MSG = 2000, CAP_ALL = 12000, MAX_TURNS = 5;

const drop = j => {
  const { _fwd_md, _fwd_html, _fwd_clean_html, output, ...rest } = j;
  return rest;
};
const field = (s, n) => {
  const r = new RegExp('(?:\\*\\*)?' + n + ':(?:\\*\\*)?[ \\t]*(.+)', 'i');
  const f = s.match(r);
  return f ? f[1].replace(/\*\*/g, '').replace(/[<>[\]()]/g, ' ').replace(/\s+/g, ' ').trim() : '';
};
const norm = s => String(s).replace(/\s+/g, ' ').trim().toLowerCase().slice(0, 400);

const items = $input.all();
const out = [];

for (let i = 0; i < items.length; i++) {
  const j = items[i].json || {};
  const md = String(j._fwd_md || '');

  // 1. Locate quoted-header boundaries. The regex is built per item so its
  //    lastIndex cannot leak from one iteration into the next.
  const rx = /(?:^|\n)[ \t>*_-]*(?:-{2,}\s*(?:Forwarded message|Original Message)\s*-{2,}|(?:\*\*)?From:(?:\*\*)?[ \t]*\S)/gi;
  const marks = [];
  let mm;
  while ((mm = rx.exec(md)) !== null) { marks.push(mm.index); rx.lastIndex = mm.index + 1; }

  if (!marks.length) {
    out.push({ json: { ...drop(j), _fwd_thread: '' }, pairedItem: { item: i } });
    continue;
  }

  // 2. Slice between boundaries. Text before marks[0] is the covering note - skipped.
  const segs = marks.map((s, k) => md.slice(s, k + 1 < marks.length ? marks[k + 1] : md.length));

  // 3. Parse header + body out of each segment.
  const turns = segs.map(seg => {
    let hdrEnd = 0, h;
    const hx = /(?:\*\*)?(?:From|Sent|Date|To|Cc|Bcc|Subject|Reply-To):(?:\*\*)?[ \t]*.*/gi;
    while ((h = hx.exec(seg)) !== null) { if (h.index < 600) hdrEnd = h.index + h[0].length; }
    const body = seg.slice(hdrEnd)
      .replace(/^[\s>*_-]+/, '')
      .replace(/\[([^\]]*)\]\([^)]*\)/g, '$1')
      .replace(/\s+/g, ' ')
      .trim();
    return { who: field(seg, 'From') || 'Unknown', when: field(seg, 'Sent') || field(seg, 'Date'), body };
  }).filter(t => t.body.length > 20);

  // 4. Drop whichever segment already became queryText, so the agent is not shown
  //    the same text twice. Primary signal is the agent's own `source`; the
  //    normalised comparison is a second line of defence.
  const q = norm(j.queryText || '');
  let kept = turns;
  if (j.fwd_source === 'quoted' && kept.length) kept = kept.slice(1);
  kept = kept.filter(t => !(q && norm(t.body) === q));

  // 5. Quoted chains read newest-first - flip to oldest-first, keep the most recent few.
  const _fwd_thread = kept.reverse().slice(-CAP_ALL && MAX_TURNS)
    .map(t => `--- From: ${t.who} | ${t.when} ---\n${t.body.slice(0, CAP_MSG)}`)
    .join('\n\n').slice(0, CAP_ALL);

  out.push({ json: { ...drop(j), _fwd_thread }, pairedItem: { item: i } });
}

return out;

