parameters.jsCode:
// Fold the classifier's label back onto the record and drop the scratch keys.
// chainLlm emits only { output: ... }, so the record arrives here already
// rejoined by "Merge - Record + Intent" -- do NOT reach back with
// $('Merge Cleaned Query').item, that lineage does not survive the LLM node.
//
// Falls back to non_actionable when the parser returns nothing or an unknown
// label, so a classifier failure degrades to an unfiltered draft rather than
// poisoning the retrieval filter with a bad value.
const VALID = ['appointment','assessment_request','service_clarification','operational_info',
               'volunteer_internship','staff_referral','partnership','non_actionable'];
const { output, queryBody, ...orig } = $json;
const raw = String((output && output.intent) || '').trim().toLowerCase();
const intent = VALID.includes(raw) ? raw : 'non_actionable';
return { json: { ...orig, intent, intent_classified: VALID.includes(raw) } };

// Did the search return a folder whose name EXACTLY matches our target?
const target = ($('Define Folder Name').first().json.folder_name || '').trim().toLowerCase();
const items = $input.all().map(i => i.json || {});
const match = items.find(r => String(r.name || '').trim().toLowerCase() === target);
if (match) {
  return [{ json: { found: true, folder_id: match.id, folder_name: match.name } }];
}
return [{ json: { found: false, folder_name: $('Define Folder Name').first().json.folder_name } }];

// Both branches land here: existing folder carries folder_id, a freshly
// created folder carries id. Emit one consistent folder_id downstream.
const j = $input.first().json || {};
const folder_id = j.folder_id || j.id || '';
const folder_name = j.folder_name || j.name || '';
return [{ json: { folder_id, folder_name } }];

// Did the search return a folder whose name EXACTLY matches our target?
const target = ($('Define Folder Name').first().json.child_folder_name || '').trim().toLowerCase();
const items = $input.all().map(i => i.json || {});
const match = items.find(r => String(r.name || '').trim().toLowerCase() === target);
if (match) {
  return [{ json: { found: true, folder_id: match.id, folder_name: match.name } }];
}
return [{ json: { found: false, folder_name: $('Define Folder Name').first().json.child_folder_name } }];

// Restore the full filtered email set after the folder-provisioning chain,
return $('Filter - Exclude Own Mailbox').all().map(r => ({
  json: {
    id: r.json.id,
    conversationId: r.json.conversationId,
    subject: r.json.subject,
    from: r.json.from,
    sentDateTime: r.json.sentDateTime,
    createdDateTime: r.json.createdDateTime,
    body: r.json.body,
    toRecipients: r.json.toRecipients,
    ccRecipients: r.json.ccRecipients,
  },
}));

// Hand the record back to the loop: the raw inbound message plus the thread
// text just built. One of these accumulates per email; the loop releases them
// all on the done branch, where Build Query takes over for the whole batch.
const email = $('Loop Over Inbound').first().json;
return [{ json: { ...email, threadHistory: $json.threadHistory || '' } }];

// Both branches land here: existing folder carries folder_id, a freshly
// created folder carries id. Emit one consistent folder_id downstream.
const j = $input.first().json || {};
const child_folder_id = j.folder_id || j.id || '';
const child_folder_name = j.folder_name || j.name || '';
return [{ json: { child_folder_id, child_folder_name } }];

