}) }}

parameters.jsCode:
// Flatten the Azure AI Search REST response into the precedent block that the
// disabled "AI Agent (Draft)" used to receive from its vector-store tool.
//
// runOnceForAllItems: one search response per inbound record, mapped 1:1 in
// input order.
// Degrades quietly: if the embed or search call was passed through by
// onError=continueRegularOutput, there is no `value` array, precedents is ''
// and the chain still drafts from the inbound email + thread history alone.
const searches = $input.all();
// Output 7 of "Switch - Intent" is the partnership branch -- pair against that
// output only, NOT $('Merge Cleaned Thread'), which still holds every intent.
const records  = $('Switch - Intent').all(7);

// Every custom field lives inside metadata.attributes as a key/value string
// pair -- that is the node-compatible index schema, not top-level fields.
const attr = (d, k) => {
  const list = ((d || {}).metadata || {}).attributes || [];
  const hit = list.find(a => a && a.key === k);
  return hit && hit.value != null ? String(hit.value) : '';
};

const buildPrecedents = (docs) => docs.map((d, i) => {
  const question = String(d.content || '').trim();          // "Subject: ...\n\n<question>"
  const reply    = attr(d, 'reply_text').trim();
  const subject  = attr(d, 'reply_subject');
  const when     = String(d.reply_sent_at || attr(d, 'reply_sent_at') || '').slice(0, 10);
  if (!question && !reply) return '';
  return [
    `--- PRECEDENT ${i + 1}${when ? ` (replied ${when})` : ''} ---`,
    `PAST QUESTION:\n${question}`,
    `REPLY SUBJECT: ${subject}`,
    `REPLY SENT:\n${reply}`
  ].join('\n');
}).filter(Boolean).join('\n\n').slice(0, 24000);


// ---- Retrieval log fields (raw passthrough for the XLSX draft log) --------
// Taken straight from the search response: document ids in rank order, and
// each document's reranker|search score in the same order. No derived scoring.
const idsOf = (docs) => docs.map(d => String((d || {}).id || '')).filter(Boolean).join(', ');
const scoresOf = (docs) => docs.map(d => {
  const r = (d || {})['@search.rerankerScore'], s = (d || {})['@search.score'];
  return `${r == null ? '' : r}|${s == null ? '' : s}`;
}).join(', ');
// The filter sent by "HTTP - Retrieve Precedents (Partnership)", rebuilt from the same record
// values so the log shows what was searched. KEEP IN SYNC with that node.
const filterOf = (rec) =>
  `metadata/attributes/any(a: a/key eq 'sender_role' and a/value eq '${rec.sender_role}') and `
  + `metadata/attributes/any(a: a/key eq 'intent' and a/value eq 'partnership')`;

return searches.map((s, i) => {
  const rec  = ((records[i] || {}).json) || {};
  const docs = Array.isArray((s.json || {}).value) ? s.json.value : [];
  return {
    json: {
      ...rec,
      precedents: buildPrecedents(docs),
      precedent_count: docs.length,
      precedent_ids: idsOf(docs),
      precedent_scores: scoresOf(docs),
      retrieval_filter: filterOf(rec),
      retrieval_docs: docs      // raw passthrough for inspection; dropped by the LLM chain
    },
    pairedItem: { item: i }
  };
});

// Build a FORWARD note for partnership enquiries. Same deterministic renderer as
// "Build Outlook HTML" (identical esc/inlineText/list/paragraph helpers and the
// same buildBody parser) -- the ONLY differences are at the emit step:
//   * the message is addressed to the partnership handler, not the enquirer, so
//     the greeting is a fixed "Dear Colleague," -- never the sender's name
//   * the LLM text is a handover note, and the ORIGINAL enquiry is appended
//     verbatim underneath in a quoted block, the way a real forward looks
//   * subject is "FW: <inbound subject, RE:/FW: chain stripped>"
//   * emits fwd_body_html + fwd_out_subject + fwd_out_to for the Outlook node
//
// KEEP IN SYNC: everything above the emit step is copied from "Build Outlook
// HTML". Fixes there (list numbering, greeting stripper, linkifier) must be
// applied here too.
//
// Recipient comes from $vars.PARTNERSHIP_FORWARD_TO -- set it before enabling
// the Outlook node, or fwd_out_to is empty and the draft has no To: line.

// ---- Theme (UCS house style: Word-generated Outlook mail) -----------------
// Mirrors the markup a real UCS sent reply carries: MsoNormal paragraphs,
// Aptos 11.5pt black body, [NUS Restricted] classification line, Calibri 10pt
// "::"-separated signature, red confidentiality notice. No card, no orange
// chrome -- the draft must look like it was typed in Outlook.
const FONT       = 'Aptos,sans-serif';
const SIG_FONT   = '"Calibri",sans-serif';
const ACCENT     = '#1F497D';   // signature blue
const TEXT       = 'black';
const MUTED      = '#1F497D';
const FAINT      = '#666666';
const CALLOUT_BG = 'yellow';    // review-note highlight (Word "background:yellow")
const LINK       = 'color:#467886; text-decoration:underline;';
const CLASSIFICATION = '[NUS Restricted]';

// A blank MsoNormal paragraph -- Word's block separator. Blocks are joined with
// this instead of CSS margins, which Outlook desktop strips.
const SPACER = `<p class="MsoNormal"><span style="font-size:11.5pt; color:black">&nbsp;</span></p>`;

// ---- Scaffold -------------------------------------------------------------
const HEAD = `<html><head>
<meta http-equiv="Content-Type" content="text/html; charset=utf-8">
<meta name="Generator" content="Microsoft Word 15 (filtered medium)">
<style>
<!--
@font-face
\t{font-family:"Cambria Math"}
@font-face
\t{font-family:Calibri}
@font-face
\t{font-family:Aptos}
p.MsoNormal, li.MsoNormal, div.MsoNormal
\t{margin:0cm;
\tfont-size:12.0pt;
\tfont-family:"Aptos",sans-serif}
a:link, span.MsoHyperlink
\t{color:#467886;
\ttext-decoration:underline}
span.EmailStyle19
\t{font-family:"Aptos",sans-serif;
\tcolor:windowtext}
.MsoChpDefault
\t{font-size:10.0pt}
@page WordSection1
\t{margin:72.0pt 72.0pt 72.0pt 72.0pt}
div.WordSection1
\t{}
-->
</style></head>
<body lang="EN-SG" link="#467886" vlink="#96607D" style="word-wrap:break-word">
<div class="WordSection1">
${SPACER}
<p class="MsoNormal"><b><span style="font-size:11.5pt; color:black">${CLASSIFICATION}</span></b></p>
${SPACER}`;

const FOOTER = `${SPACER}
<p class="MsoNormal"><span style="font-size:11.5pt; color:black">Thank you.</span></p>
<p class="MsoNormal"><span style="font-size:10.0pt; font-family:${SIG_FONT}; color:black">&nbsp;</span></p>
<p class="MsoNormal"><b><span style="font-size:10.0pt; font-family:${SIG_FONT}; color:${ACCENT}">University Counselling Services (UCS) ::</span></b><span style="font-size:10.0pt; font-family:${SIG_FONT}; color:${ACCENT}"> National University of Singapore :: 20 Lower Kent Ridge Road, Level 2, Singapore 119080 :: 65-6516 2376(DID) :: 65-6516 7777 (24-hour Lifeline NUS in the event of a life threatening psychological emergency) :: <a href="mailto:ucs@nus.edu.sg"><span style="color:blue">ucs@nus.edu.sg</span></a>&nbsp;(E) :: </span><u><span style="font-size:10.0pt; font-family:${SIG_FONT}; color:blue"><a href="https://nus.edu.sg/hwb/ucs/"><span style="color:blue">University Counselling Services &ndash; NUS Health &amp; Wellbeing</span></a> </span></u><span style="font-size:10.0pt; font-family:${SIG_FONT}; color:${ACCENT}">(W) :: Company Registration No: 200604346E<br><br></span><span style="font-size:10.0pt; font-family:${SIG_FONT}; color:red">Important: This email is confidential and may be privileged. If you are not the intended recipient, please delete it and notify us immediately; you should not copy or use it for any purpose, nor disclose its contents to any other person.</span></p>
<p class="MsoNormal"><span style="font-size:10.0pt">&nbsp;</span></p>
<p class="MsoNormal">&nbsp;</p>`;

const TAIL = `</div></body></html>`;

// ---- Inline text: escape -> **bold** -> [text](url) -> bare URLs/emails ----
function esc(s){ return String(s == null ? '' : s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;'); }

function inlineText(s){
  s = esc(s);
  s = s.replace(/\*\*([^*]+)\*\*/g, '<b>$1</b>');
  const tokens = [];
  const stash = h => { tokens.push(h); return '\u0000' + (tokens.length - 1) + '\u0000'; };
  s = s.replace(/\[([^\]]+)\]\((https?:\/\/[^\s)]+|mailto:[^\s)]+)\)/g, (m,t,u) => stash('<a href="'+u+'" target="_blank" title="'+u+'">'+t+'</a>'));
  s = s.replace(/(https?:\/\/[^\s<]+[^\s<.,;:!?)\]])/g, (m,u) => stash('<a href="'+u+'" target="_blank" title="'+u+'">'+u+'</a>'));
  s = s.replace(/([A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,})/g, (m,e) => stash('<a href="mailto:'+e+'">'+e+'</a>'));
  s = s.replace(/\u0000(\d+)\u0000/g, (m,i) => tokens[+i]);
  return s;
}

// ---- Block renderers (MsoNormal paragraphs, Word-style) -------------------
// Lists are plain indented paragraphs with a hard-spaced marker, exactly like
// the "(a) ... (f)" blocks in a hand-written UCS reply. No table, no callout.
function renderOrdered(items){
  return items.map((txt,i) =>
    `<p class="MsoNormal"><span style="font-size:11.5pt; color:black">${i+1}.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; ${inlineText(txt)}</span></p>`
  ).join('\n');
}

function renderUnordered(items){
  return items.map(txt =>
    `<p class="MsoNormal"><span style="font-size:11.5pt; color:black">&bull;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; ${inlineText(txt)}</span></p>`
  ).join('\n');
}

function renderParagraph(lines){
  return `<p class="MsoNormal"><span style="font-size:11.5pt; color:black">${lines.map(inlineText).join('<br>')}</span></p>`;
}

const GREETING = /^(hi|hello|hey|dear|good\s+(morning|afternoon|evening))\b.*$/i;

// ---- Sign-off detection (strip anything the agent appends as a closing) ----
// A whole line that is a valediction ("Best regards,", "Thanks", "Sincerely", ...).
const VALEDICTION = /^(thanks?(\s*(and|&)\s*regards)?|thank\s+you|many\s+thanks|best(\s+(regards|wishes))?|kind(est)?\s+regards|warm(est)?\s+regards|regards|sincerely|yours\s+(sincerely|faithfully|truly)|respectfully|cheers)[.,!\s]*$/i;
// A short trailing line that is a name / placeholder / team-or-org signature
// e.g. "[Your Name]", "Jane Tan", "University Counselling Service Team", "UCS Team".
const SIGN_NAME = /^(\[[^\]]*\]|[A-Z][A-Za-z.'\u2019-]*(?:\s+[A-Z][A-Za-z.'\u2019-]*){0,4}|(?:the\s+)?(?:ucs|front\s+desk|university\s+counsell?ing\s+services?)(?:\s+team)?|.*\bteam$)$/i;
// A valediction glued to the end of the last sentence ("...let us know. Best regards,").
const TRAIL_VALEDICTION = /[\s,;:-]+(thanks?(\s*(and|&)\s*regards)?|best\s+regards|kind\s+regards|warm\s+regards|regards|sincerely|cheers)[.,!\s]*$/i;

// ---- Deterministic greeting (replaces the agent's "Dear [Name]," placeholder) ----
const GREETING_WORD    = 'Dear';      // 'Hi' if preferred
const NAME_PLACEHOLDER = '[Name]';    // used when no name is found in the body OR the email address
// A greeting line to drop from the agent output (incl. bracketed "Dear [Name]," placeholders).
const STRIP_GREETING = /^(hi|hello|hey|dear|good\s+(morning|afternoon|evening))\b[\w\s.,'\[\]()\/-]{0,40},?\s*$/i;

const TITLES = /^(dr|mr|mrs|ms|miss|mx|prof|professor|assoc|a\/?prof|mdm|sir|madam)\.?$/i;
const BANNED = /^(ucs|university|counselling|counseling|services|service|front|desk|team|the|student|staff|clinician|sir|madam|dear|hi|hello|hey|regards|thanks|thank|best|kind|warm|warmest|sincerely|cheers|yours|wishes|cordially|respectfully|name|sender|to|whom|monday|tuesday|wednesday|thursday|friday|saturday|sunday|january|february|march|april|may|june|july|august|september|october|november|december)$/i;
function titleCase(w){ return w ? w.charAt(0).toUpperCase() + w.slice(1).toLowerCase() : ''; }
function cleanFirst(cand){
  let toks = String(cand || '').trim().split(/\s+/).filter(Boolean);
  while (toks.length && TITLES.test(toks[0])) toks.shift();
  let f = (toks[0] || '').replace(/[^A-Za-z'\u2019-]/g,'');
  if (f.length < 2 || BANNED.test(f)) return '';
  return titleCase(f);
}
// Display names that are role/department mailboxes, not people.
const ORG_NAME = /\b(nus|ucs|yale|duke|office|dept|department|admin|administrator|registrar|admissions?|faculty|school|college|centre|center|team|services?|support|helpdesk|info|enquir\w*|inquir\w*|no[-\s]?reply|do[-\s]?not[-\s]?reply|notification|mailer|system|group|committee|society|library|bursar|finance)\b/i;

function firstNameFromDisplay(raw){
  let n = String(raw || '').trim();
  if (!n || n.indexOf('@') !== -1) return '';
  if (ORG_NAME.test(n)) return '';   // role mailbox -> fall through to the body, then [Name]
  if (/\d/.test(n)) return '';       // "Helpdesk 2", auto-provisioned accounts
  if (n.indexOf(',') !== -1){ const p = n.split(','); n = (p[1] || p[0]).trim(); } // "Last, First" -> First
  return cleanFirst(n);
}
function firstNameFromEmail(email){
  const local = String(email || '').split('@')[0] || '';
  const cand = (local.split(/[._+-]/)[0] || '');
  return /^[A-Za-z]{2,}$/.test(cand) ? titleCase(cand) : ''; // reject IDs like e0123456
}
// detect the name the sender signs with in their own message body (whitespace-collapsed)
const NAME   = "[A-Z][A-Za-z'\\u2019.\\-]+(?:\\s+[A-Z][A-Za-z'\\u2019.\\-]+){0,1}";
const STRONG = "(?:warmest\\s+regards|warm\\s+regards|kindest\\s+regards|kind\\s+regards|best\\s+regards|best\\s+wishes|thanks\\s+and\\s+regards|yours\\s+sincerely|yours\\s+faithfully|yours\\s+truly|sincerely|cordially)";
const WEAK   = "(?:regards|thank\\s+you|thanks|cheers|best)";
function firstNameFromBody(body){
  const s = String(body || '');
  if (!s) return '';
  let m, cand = '';
  const reStrong = new RegExp(STRONG + "\\s*[,!.:\\-\\u2013\\u2014]*\\s*(" + NAME + ")", 'gi');
  while ((m = reStrong.exec(s)) !== null) cand = m[1];   // strong sign-off: last wins
  let f = cleanFirst(cand);
  if (f) return f;
  cand = '';
  const reWeak = new RegExp(WEAK + "\\s*[,!.:\\-\\u2013\\u2014]*\\s*(" + NAME + ")", 'gi');
  while ((m = reWeak.exec(s)) !== null){                 // weak sign-off: only if name is at the very end
    const after = s.slice(m.index + m[0].length).replace(/[\s.,!]+/g,'');
    if (after.length <= 2) cand = m[1];
  }
  f = cleanFirst(cand);
  if (f) return f;
  const intro = s.slice(0, 400).match(new RegExp("(?:my name is|i am|i'm|this is)\\s+(" + NAME + ")", 'i'));
  return intro ? cleanFirst(intro[1]) : '';
}
function makeGreeting(displayName, email, bodyText){
  // Order of preference:
  // 1) the Outlook display name on the From address (From.emailAddress.name),
  //    unless it looks like a role/department mailbox or contains a digit
  // 2) else the name the sender signs with in their own incoming email body
  // 3) else the [Name] placeholder for the front-desk officer to fill in
  //
  // Display name first because "Clean Query (LLM)" strips sign-offs from the
  // body, so firstNameFromBody() only fires on "my name is ..." style text.
  const first = firstNameFromDisplay(displayName)
             // || firstNameFromEmail(email)          // optional: address local-part. NO trailing semicolon.
             || firstNameFromBody(bodyText);
  return first ? `${GREETING_WORD} ${first},` : `${GREETING_WORD} ${NAME_PLACEHOLDER},`;
}

// ---- Parse plain text into blocks -----------------------------------------
function buildBody(raw){
  let text = String(raw == null ? '' : raw);
  text = text.replace(/```[a-z]*\n?/gi,'').replace(/```/g,''); // drop code fences
  text = text.replace(/\r\n?/g,'\n').trim();

  // Strip a trailing sign-off / signature the agent may still emit. Walk up from the
  // end consuming blank / valediction / short name-or-team-or-placeholder lines (max 6);
  // if at least one valediction was seen, cut the whole region. Removes blocks like:
  //   Best regards,
  //   [Your Name]
  //   University Counselling Service Team
  {
    let tl = text.split('\n').map(l => l.replace(/\s+$/,''));
    while (tl.length && tl[tl.length-1].trim() === '') tl.pop();
    let i = tl.length - 1, hasVal = false, region = 0;
    while (i >= 0 && region < 6){
      const ln = tl[i].trim();
      if (ln === ''){ i--; region++; continue; }
      if (VALEDICTION.test(ln)){ hasVal = true; i--; region++; continue; }
      if (ln.length <= 60 && SIGN_NAME.test(ln)){ i--; region++; continue; }
      break;
    }
    if (hasVal){ tl.length = i + 1; text = tl.join('\n').replace(/\s+$/,''); }
  }

  const lines = text.split('\n');
  const blocks = [];
  let cur = null, blank = false;
  for (const raw2 of lines){
    const t = raw2.trim();
    // A blank line ends a PARAGRAPH but not a LIST. Models routinely put a blank
    // line between "1." and "2."; closing the block there gave each item its own
    // callout box with the counter restarting at 1. Only a non-list line (or a
    // change of list type) closes a list now.
    if (t === ''){ blank = true; continue; }
    const om = t.match(/^(?:\d+)[.)]\s+(.*)$/);
    const um = t.match(/^[-*\u2022\u00b7]\s+(.*)$/);
    if (om){
      if (!cur || cur.type !== 'ol'){ cur = { type:'ol', items:[] }; blocks.push(cur); }
      cur.items.push(om[1]);
    } else if (um){
      if (!cur || cur.type !== 'ul'){ cur = { type:'ul', items:[] }; blocks.push(cur); }
      cur.items.push(um[1]);
    } else {
      if (!cur || cur.type !== 'p' || blank){ cur = { type:'p', lines:[t] }; blocks.push(cur); }
      else { cur.lines.push(t); }
      if (GREETING.test(t) && cur.lines.length === 1){ cur = null; } // greeting stands alone
    }
    blank = false;
  }

  // Drop the agent's greeting line entirely - a deterministic greeting is prepended in
  // the emit step. This is what removes "Dear [Name]," (and any other agent greeting).
  if (blocks.length && blocks[0].type === 'p' && blocks[0].lines.length === 1 && STRIP_GREETING.test(blocks[0].lines[0])){
    blocks.shift();
  }

  // Fallback: trim a valediction glued onto the end of the last line
  // ("...do let us know. Best regards,") that the block strip above wouldn't catch.
  if (blocks.length){
    const lb = blocks[blocks.length - 1];
    if (lb.type === 'p' && lb.lines.length){
      lb.lines[lb.lines.length - 1] = lb.lines[lb.lines.length - 1].replace(TRAIL_VALEDICTION, '').trim();
      while (lb.lines.length && lb.lines[lb.lines.length - 1] === '') lb.lines.pop();
      if (!lb.lines.length) blocks.pop();
    }
  }

  const rendered = blocks.map(b => {
    if (b.type === 'ol') return renderOrdered(b.items);
    if (b.type === 'ul') return renderUnordered(b.items);
    return renderParagraph(b.lines);
  }).filter(Boolean);

  if (!rendered.length) rendered.push(SPACER);
  return rendered.join('\n' + SPACER + '\n');
}


// ---- Emit -----------------------------------------------------------------
const GREETING_FWD = 'Dear Colleague,';
const SUBJ_PREFIX_FWD = /^(\s*(re|res|aw|sv|vs|antwort|fw|fwd|fwdd|tr|wg|rv|enc)\s*(\[\d+\])?\s*:\s*)+/i;
const FORWARD_TO = String($vars.PARTNERSHIP_FORWARD_TO || '').trim();

// The original enquiry, rendered as a quoted block under the handover note.
function quotedOriginal(j){
  const from    = esc(j.inbound_from_name ? `${j.inbound_from_name} <${j.inbound_from}>` : (j.inbound_from || 'unknown sender'));
  const when    = esc(String(j.question_received_at || ''));
  const subject = esc(String(j.inbound_subject || ''));
  // queryText carries the "Subject: ...\n\n" prefix from Build Query -- strip it,
  // the subject is shown on its own row above.
  const body    = String(j.queryText || '').replace(/^Subject:[^\n]*\n+/, '');
  const rendered = buildBody(body);
  return `<div style="border:none; border-top:solid #E1E1E1 1.0pt; padding:3.0pt 0cm 0cm 0cm">
<p class="MsoNormal"><b><span style="font-size:11.0pt; font-family:${SIG_FONT}">From:</span></b><span style="font-size:11.0pt; font-family:${SIG_FONT}"> ${from}<br><b>Sent:</b> ${when}<br><b>Subject:</b> ${subject}</span></p>
</div>
${SPACER}
${rendered}`;
}

const all = $input.all();
const out = [];
for (let idx = 0; idx < all.length; idx++){
  const j = all[idx].json || {};

  const raw  = j.output != null ? j.output : (j.text != null ? j.text : (j.html != null ? j.html : ''));
  const note = buildBody(raw);

  // Fixed greeting: this message goes to the partnership handler, so no sender
  // name resolution at all -- using the enquirer's name here would be wrong.
  const greetingHtml = renderParagraph([GREETING_FWD]);

  const fwd_out_subject = ('FW: ' + String(j.inbound_subject || '').replace(SUBJ_PREFIX_FWD, '').trim()).slice(0, 255);
  // Blank MsoNormal paragraph after the greeting, as in a hand-written UCS reply.
  const full = HEAD + '\n' + greetingHtml + '\n' + SPACER + '\n' + note + '\n' + quotedOriginal(j) + '\n' + FOOTER + '\n' + TAIL;

  out.push({
    json: {
      ...j,
      fwd_body_html:   full,
      fwd_out_subject,
      fwd_out_to:      FORWARD_TO,
      forward_reason:  'partnership',
      greeting:        GREETING_FWD
    },
    pairedItem: { item: idx }
  });
}
return out;

parameters.inputSchema:
{
  "type": "object",
  "properties": {
    "mentioned_names": {
      "type": "array",
      "items": {
        "type": "string"
      },
      "description": "Full roster names of UCS clinicians referred to in QUESTION. Empty array if none."
    }
  },
  "required": [
    "mentioned_names"
  ]
}

parameters.jsCode:
// Resolve the clinician(s) this message refers to, if any.
//
// Items arrive from "Merge - Record + Clinician" (combine-by-position): each
// item carries BOTH the full record AND the chain output under `output`.
// Reads only the item's own json -- no cross-node $('...').item reach-back,
// matching the pattern used by "Apply Intent" and "Apply Consult".
//
// MODE: "Run Once for All Items". Mapping is strictly 1:1 -- never filter here,
// or the downstream combine-by-position merge will misalign.
//
// The extraction chain already matches against the ten-name clinician roster,
// so every name arriving here is meant to be a clinician. This node only
// removes the sender's own name and joins what is left. A name is still not
// proof of an open case -- the gate prompt is told to judge that from context.

const TITLE_RE = /^\s*(?:ms|mrs|mr|dr|miss|prof|professor)\.?\s+/i;

const norm = (s) => String(s || '')
  .toLowerCase()
  .replace(TITLE_RE, '')
  .replace(/[^a-z\s'-]/g, '')
  .replace(/\s+/g, ' ')
  .trim();

// Name tokens recoverable from the sender's address. Matric-style local parts
// (e1518424@u.nus.edu) yield nothing -- for those this guard simply does not
// fire, which is why it is a filter and not a test. The extraction prompt is
// the primary self-name defence; this is a backstop.
const senderTokens = (from) => {
  const local = String(from || '').toLowerCase().split('@')[0] || '';
  return new Set(
    local.split(/[._\-+]/).filter((t) => t.length > 2 && !/^\d+$/.test(t))
  );
};

return $input.all().map((item) => {
  const j = item.json;
  const parsed = (j.output && typeof j.output === 'object') ? j.output : {};
  const names = Array.isArray(parsed.mentioned_names) ? parsed.mentioned_names : [];

  const mine = senderTokens(j.inbound_from);
  const myName = norm(j.inbound_from_name);

  // Drop anything that is really the sender writing their own name.
  const isSelf = (raw) => {
    const key = norm(raw);
    if (!key) return false;
    if (myName && (key === myName || myName.split(' ').every((p) => key.includes(p)))) return true;
    const parts = key.split(' ').filter(Boolean);
    return parts.length > 0 && mine.size > 0 && parts.every((p) => mine.has(p));
  };

  const seen = new Set();
  const clinicians = [];
  for (const raw of names) {
    const clean = String(raw || '').trim();
    const key = norm(clean);
    if (!key) continue;
    if (isSelf(clean)) continue;
    if (seen.has(key)) continue;
    seen.add(key);
    clinicians.push(clean);
  }

  const { output, ...rest } = j;
  return { json: { ...rest, assigned_clinician: clinicians.length ? clinicians.join(', ') : 'none' } };
});

// Set both consult flags on the record and drop the LLM wrapper.
//
// consult_required is DETERMINISTIC: true whenever Code - Derive assigned_clinician
// resolved at least one clinician (assigned_clinician is 'none' or a
// comma-separated list of names). It replaced the Classify Consult (LLM) gate.
//
// consult_judgement comes from Classify Consult Judgement (LLM).
//
// Items arrive from "Merge - Record + Consult" (combine-by-position, 2 inputs):
// input 0 = the record, input 1 = Classify Consult Judgement (LLM) ->
// output.consult_judgement. Reads only the item's own json -- no cross-node
// $('...').item reach-back, matching the pattern used by "Apply Intent".
//
// MODE: "Run Once for All Items". Mapping is strictly 1:1 -- never filter here,
// or the downstream combine-by-position merge will misalign.

const toBool = (v) => {
  if (typeof v === 'string') return v.trim().toLowerCase() === 'true';
  return v === true;
};

return $input.all().map((item) => {
  const j = item.json;
  const parsed = (j.output && typeof j.output === 'object') ? j.output : {};
  const clinician = String(j.assigned_clinician || 'none').trim().toLowerCase();

  const { output, ...rest } = j;
  return { json: {
    ...rest,
    consult_required: clinician !== '' && clinician !== 'none',
    consult_judgement: toBool(parsed.consult_judgement),
  } };
});

