parameters.jsCode:
// Deterministic read of the splitter's answer. Any failure -- bad JSON, an empty
// list, or a failed call passed through by continueRegularOutput -- collapses to a
// single question, which sends the email down today's single-question path.
const j = $json;
const body = String(j.queryText || '').replace(/^Subject:[^\n]*\n\n/, '').trim();
const raw = j.output ?? j.text ?? '';
let parsed = null;
if (raw && typeof raw === 'object') {
  parsed = raw;
} else {
  const s = String(raw).trim().replace(/^```(?:json)?\s*/i, '').replace(/```\s*$/, '').trim();
  try { parsed = JSON.parse(s); } catch (e) { parsed = null; }
}
const list = Array.isArray(parsed) ? parsed
  : (parsed && Array.isArray(parsed.questions) ? parsed.questions : []);
const seen = new Set();
const questions = [];
for (const q of list) {
  const t = String(q == null ? '' : q).replace(/\s+/g, ' ').trim();
  if (!t || seen.has(t.toLowerCase())) continue;
  seen.add(t.toLowerCase());
  questions.push(t.slice(0, 1000));
  if (questions.length >= 6) break;
}
// strip the splitter's own output: on the multi path nothing downstream blanks it,
// and Build Outlook HTML falls back through output ?? text
const { output, text, ...rest } = j;
return { json: { ...rest,
  questions: questions.length ? questions : [body],
  question_count: questions.length > 1 ? questions.length : 1 } };

